def format_usd_parens(amount):
    if amount < 0:
        return f"(${-amount:,.2f})"
    return f"${amount:,.2f}"

def format_accounting(amount):
    if amount == 0:
        return "$0.00"
    if amount < 0:
        return f"(${-amount:,.2f})"
    return f"${amount:,.2f}"

def format_percent_from_ratio(numerator, denominator):
    if denominator == 0:
        return "N/A"
    return f"{numerator / denominator * 100:.2f}%"

def format_percent_clamped(fraction):
    clamped = max(0.0, min(1.0, fraction))
    return f"{clamped * 100:.1f}%"

def format_percent_change(old, new):
    if old == 0:
        return "N/A"
    value = (new - old) / old * 100
    sign = "+" if value >= 0 else "-"
    return f"{sign}{abs(value):.1f}%"

def oxford_join(items):
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + f", and {items[-1]}"

